<script setup>
import InputError from '@/Components/InputError.vue';
import { Link, useForm } from '@inertiajs/vue3';

const props = defineProps({ product: { type: Object, default: null } });
const featureRows = props.product?.feature_records?.length
    ? props.product.feature_records.map(({ name, description, icon, is_active }) => ({ name, description: description || '', icon: icon || '', is_active }))
    : (props.product?.features || []).map((name) => ({ name, description: '', icon: '', is_active: true }));
const form = useForm({
    name: props.product?.name || '', code: props.product?.code || '', slug: props.product?.slug || '', category: props.product?.category || '', industry: props.product?.industry || '', tagline: props.product?.tagline || '', hero_description: props.product?.hero_description || '', short_description: props.product?.short_description || '', description: props.product?.description || '', icon: props.product?.icon || '', logo: props.product?.logo || '', cover_image: props.product?.cover_image || '', demo_url: props.product?.demo_url || '', website_url: props.product?.website_url || '', status: props.product?.status || 'draft', is_featured: props.product?.is_featured || false, sort_order: props.product?.sort_order || 0, metadata: props.product?.metadata || {}, seo_title: props.product?.seo_title || '', seo_description: props.product?.seo_description || '', features: featureRows,
    media: (props.product?.media || []).map(({ type, title, url, alt_text, is_active }) => ({ type, title: title || '', url, alt_text: alt_text || '', is_active })),
    links: (props.product?.links || []).map(({ type, label, url, is_active }) => ({ type, label, url, is_active })),
});
const submit = () => props.product ? form.put(route('admin.products.update', props.product.slug)) : form.post(route('admin.products.store'));
</script>

<template>
    <form class="form-card" @submit.prevent="submit">
        <div class="form-grid">
            <label>Name<input v-model="form.name" required /><InputError :message="form.errors.name" /></label><label>Code<input v-model="form.code" required class="uppercase" /><InputError :message="form.errors.code" /></label><label>Slug<input v-model="form.slug" required /><InputError :message="form.errors.slug" /></label><label>Category<input v-model="form.category" required /><InputError :message="form.errors.category" /></label><label>Industry<input v-model="form.industry" required /><InputError :message="form.errors.industry" /></label><label>Status<select v-model="form.status"><option value="draft">Draft</option><option value="active">Active</option><option value="inactive">Inactive</option><option value="archived">Archived</option></select><InputError :message="form.errors.status" /></label><label>Sort order<input v-model.number="form.sort_order" type="number" min="0" /><InputError :message="form.errors.sort_order" /></label><label>Icon key<input v-model="form.icon" /><InputError :message="form.errors.icon" /></label><label>Logo path or URL<input v-model="form.logo" /><InputError :message="form.errors.logo" /></label><label>Cover image path or URL<input v-model="form.cover_image" /><InputError :message="form.errors.cover_image" /></label><label>Demo URL<input v-model="form.demo_url" type="url" /><InputError :message="form.errors.demo_url" /></label><label>Product URL<input v-model="form.website_url" type="url" /><InputError :message="form.errors.website_url" /></label>
        </div>
        <label class="flex items-center gap-3"><input v-model="form.is_featured" type="checkbox" class="!mt-0 rounded border-slate-300 text-[#0797A5]" />Featured on public website</label>
        <label>Card description<input v-model="form.short_description" required /><InputError :message="form.errors.short_description" /></label><label>Headline<input v-model="form.tagline" required /><InputError :message="form.errors.tagline" /></label><label>Hero supporting copy<textarea v-model="form.hero_description" rows="3" /><InputError :message="form.errors.hero_description" /></label><label>Full description<textarea v-model="form.description" required rows="6" /><InputError :message="form.errors.description" /></label>

        <section class="space-y-4 border-t border-slate-200 pt-6"><div class="flex items-center justify-between"><div><h2 class="text-xl font-bold text-slate-900">Features</h2><p class="text-sm text-slate-500">Capabilities displayed on the product page.</p></div><button type="button" class="form-secondary-button" @click="form.features.push({ name: '', description: '', icon: '', is_active: true })">Add feature</button></div><div v-for="(feature, index) in form.features" :key="index" class="rounded-xl border border-slate-200 p-4"><div class="form-grid"><label>Name<input v-model="feature.name" required /></label><label>Icon key<input v-model="feature.icon" /></label></div><label>Description<textarea v-model="feature.description" rows="2" /></label><div class="flex justify-between"><label class="flex items-center gap-2"><input v-model="feature.is_active" type="checkbox" class="!mt-0" />Active</label><button type="button" class="text-sm font-bold text-red-600" @click="form.features.splice(index, 1)">Remove</button></div><InputError :message="form.errors[`features.${index}.name`]" /></div></section>

        <section class="space-y-4 border-t border-slate-200 pt-6"><div class="flex items-center justify-between"><div><h2 class="text-xl font-bold text-slate-900">Media</h2><p class="text-sm text-slate-500">Screenshots, videos, and documents.</p></div><button type="button" class="form-secondary-button" @click="form.media.push({ type: 'screenshot', title: '', url: '', alt_text: '', is_active: true })">Add media</button></div><div v-for="(item, index) in form.media" :key="index" class="rounded-xl border border-slate-200 p-4"><div class="form-grid"><label>Type<select v-model="item.type"><option value="screenshot">Screenshot</option><option value="video">Video</option><option value="document">Document</option></select></label><label>Title<input v-model="item.title" /></label><label>URL<input v-model="item.url" type="url" required /></label><label>Alternative text<input v-model="item.alt_text" /></label></div><div class="flex justify-between"><label class="flex items-center gap-2"><input v-model="item.is_active" type="checkbox" class="!mt-0" />Active</label><button type="button" class="text-sm font-bold text-red-600" @click="form.media.splice(index, 1)">Remove</button></div><InputError :message="form.errors[`media.${index}.url`]" /></div></section>

        <section class="space-y-4 border-t border-slate-200 pt-6"><div class="flex items-center justify-between"><div><h2 class="text-xl font-bold text-slate-900">Product links</h2><p class="text-sm text-slate-500">Documentation and additional destinations.</p></div><button type="button" class="form-secondary-button" @click="form.links.push({ type: 'documentation', label: 'Documentation', url: '', is_active: true })">Add link</button></div><div v-for="(item, index) in form.links" :key="index" class="rounded-xl border border-slate-200 p-4"><div class="form-grid"><label>Type<select v-model="item.type"><option value="website">Website</option><option value="demo">Demo</option><option value="documentation">Documentation</option><option value="support">Support</option><option value="other">Other</option></select></label><label>Label<input v-model="item.label" required /></label><label>URL<input v-model="item.url" type="url" required /></label></div><div class="flex justify-between"><label class="flex items-center gap-2"><input v-model="item.is_active" type="checkbox" class="!mt-0" />Active</label><button type="button" class="text-sm font-bold text-red-600" @click="form.links.splice(index, 1)">Remove</button></div><InputError :message="form.errors[`links.${index}.url`]" /></div></section>

        <label>SEO title<input v-model="form.seo_title" /><InputError :message="form.errors.seo_title" /></label><label>SEO description<textarea v-model="form.seo_description" rows="3" /><InputError :message="form.errors.seo_description" /></label><div class="flex flex-wrap gap-3"><button class="form-button" :disabled="form.processing">{{ product ? 'Save product' : 'Create product' }}</button><Link :href="route('admin.products.index')" class="rounded-xl border border-slate-300 px-6 py-3.5 font-bold text-slate-700">Cancel</Link></div>
    </form>
</template>
